(function(){
  const params = new URLSearchParams(location.search);
  const screen = params.get('screen') || 'home';
  const proposed = params.get('proposed') === '1';
  const iso = (d) => new Date(Date.UTC(2026, 10, d, 15, 20)).toISOString();
  const proj = (id, name, kind, text, d) => ({ id, name, path: '/Users/kenneth/JusPrin/' + name + '.3mf', updatedAt: iso(d), status: { kind, text } });
  const state = {
    appearance: 'light',
    projects: [
      proj('p1', 'Calibration', 'draft', 'Draft', 9),
      proj('p2', 'Festival arrow headband', 'exported', 'G-code exported Nov 7 for Bambu Lab P1S', 7),
      proj('p3', 'Cable clip set', 'completed', 'Printed Nov 5', 5),
      proj('p4', 'Planter with drainage tray', 'sent', 'Sent Nov 3', 3),
      proj('p5', 'Desk organizer', 'draft', 'Draft', 2),
      proj('p6', 'Headphone hook', 'draft', 'Draft', 1),
    ],
    printers: [{ id: 'pr1', name: 'Bambu Lab P1S', kind: 'device', canOpenSettings: true, canRename: true, canRemove: true,
      status: 'ready', connectionLabel: 'LAN', modelText: 'P1S · 0.4 mm' }],
    onboarding: { visible: false, step: 'hidden', printersScreen: 'add_printer', signIn: 'idle', email: null, signInError: '', accountEmail: '', agentConfigured: true },
  };
  let n = 0;
  const env = (type, payload, correlationId) => ({ protocol: 'jusprin-home-bridge', version: 1, id: 'h' + (++n), type, correlationId, payload });
  const deliver = (e) => setTimeout(() => window.__jusprinBridge && window.__jusprinBridge.deliver(e), 0);
  window.wx = { postMessage(json) {
    const m = JSON.parse(json);
    if (m.type === 'hello') {
      deliver(env('hello_ack', { protocolVersion: 1 }, m.id));
      deliver(env('state', state));
      if (screen === 'history') deliver(env('screen', { screen: 'history', back: 'home' }));
    } else if (m.type === 'history_request' || m.type === 'state_request') {
      deliver(env('history', { entries: [], reportsOffered: false }, m.id));
    }
  } };
  if (!proposed) return;
  const css = `
    .nav-back { display:inline-flex; align-items:center; justify-content:center; width:var(--button-icon-width); height:var(--button-icon-height);
      border:1px solid var(--border-subtle); border-radius:var(--radius-small); color:var(--text-primary); background:var(--surface-canvas); position:relative; }
    .nav-back.hovered { background: var(--surface-subtle); }
    .nav-tip { position:absolute; top:calc(100% + 6px); left:0; white-space:nowrap; height:var(--tooltip-height); box-sizing:border-box; display:flex; align-items:center;
      padding:var(--tooltip-padding-y) var(--tooltip-padding-x); border-radius:var(--tooltip-radius); color:var(--surface-canvas); background:var(--text-primary); font:var(--font-metadata); z-index:5; }
  `;
  const apply = () => {
    const header = document.querySelector('.home-header');
    if (!header) return false;
    if (!document.getElementById('nav-css')) { const s = document.createElement('style'); s.id = 'nav-css'; s.textContent = css; document.head.appendChild(s); }
    if (screen === 'home') {
      const path = header.querySelector('.home-header-path');
      if (!path) return false;
      [...path.children].forEach((c, i) => { if (i > 0) c.remove(); });
    } else {
      const btn = header.querySelector('.history-header-start button');
      if (!btn) return false;
      btn.className = 'nav-back hovered';
      const tip = document.createElement('span'); tip.className = 'nav-tip'; tip.textContent = 'Back to Home';
      btn.appendChild(tip);
    }
    return true;
  };
  const tick = () => { if (!apply()) setTimeout(tick, 50); };
  window.addEventListener('DOMContentLoaded', tick);
})();
EOF
