111	  return `${shortPreset(process)}${filament}.${differ}`;
112	}
113	
114	// The app's own mark that the project moved on since the plan was recorded,
115	// which only the agent recording it again clears.
116	export function planInDoubt(context: WorkspaceContext): boolean {
117	  return !!context.planHeadline.trim() && context.planValidity === 'needs_reassessment';
118	}
119	
120	// The plan line's annotation: what moved since the plan was recorded, in the
121	// words the host wrote for it ("Filament changed to Generic ABS by hand"),
122	// with the Check plan link beside it; failing that, a calibration test whose
123	// steps the file lost, since in a calibration chat the test is the plan.
124	export function planNote(context: WorkspaceContext): string {
125	  if (planInDoubt(context))
126	    return context.planInvalidatedBy || 'Plan needs another look';
127	  return testStepsLost(context);
128	}
129	
130	// The presets line's annotation: the printer last reported another material
131	// than the setup's. The nozzle and the printer model are not lines of this
132	// card; the header's printer chip and the chat own those.
133	export function presetsNote(context: WorkspaceContext): string {
134	  const review = context.printerReview;
135	  if (!review?.observed?.observedAt) return '';
136	  const material = review.mismatches.find((mismatch) => mismatch.what === 'filament' && mismatch.source === 'device');
137	  return material ? `Printer last reported ${material.observed}` : '';
138	}
139	
140	function Note({ text, action }: { text: string; action?: { label: string; onClick: () => void } }) {
141	  if (!text) return null;
142	  return <p className={action ? 'current-setup-annotation current-setup-annotation--action' : 'current-setup-annotation'}>
143	    <span className="jp-icon jp-icon-triangle-alert" aria-hidden="true" />
144	    <span className="current-setup-annotation-text">{text}</span>
145	    {action && <button type="button" className="current-setup-link" onClick={action.onClick}>{action.label}</button>}
146	  </p>;
147	}
148	
149	export function SetupCard({ context, working: busy = false, historical = false, savedAt, agentAvailable = true,
150	  sent, onCompute, onViewSetup, onCheckPlan }: SetupCardProps) {
151	  if (!context) return null;
152	  // A saved card is never working, whatever the active chat happens to be
153	  // doing, and with no agent nothing is.
154	  const working = busy && !historical && agentAvailable;
155	  const ariaLabel = historical ? 'Earlier setup — saved with this conversation' : 'Current setup';
156	  const eyebrow = sent ? 'Saved sliced snapshot' : historical ? 'Earlier setup' : 'Setup summary';
157	  const saved = formatMoment(savedAt);
158	  const state = historical ? (sent ? 'Sliced & sent' : saved ? `Saved ${saved}` : '') : working ? 'AI working' : '';
159	
160	  const purpose = context.setupIntent.trim();
161	  const plan = context.planHeadline.trim();
162	  const words = !!(purpose || plan);
163	  const presets = presetsLine(context);
164	  const estimate = estimateView(context);
165	  // With no agent the card is the preset's label and offers nothing, as it
166	  // offers nothing to open when it read no settings.
167	  const offers = historical || agentAvailable;
168	  const live = !historical && agentAvailable && !working && !!onCompute;
169	  const sentWhen = sent ? formatMoment(sent.at) : '';
170	
171	  return <section className={historical ? 'current-setup' : 'current-setup current-setup--live'}
172	    data-testid="current-setup" aria-label={ariaLabel} aria-busy={working || undefined}>
173	    <div className="current-setup-header"><span className="current-setup-label">{eyebrow}</span>
174	      {state && <span className="current-setup-state">{state}</span>}</div>
175	    {words && <>
176	      {purpose && <h2 className="current-setup-title" title={purpose}>{purpose}</h2>}
177	      {plan && <p className="current-setup-strategy">{plan}</p>}
178	      <Note text={planNote(context)} action={live && onCheckPlan && planInDoubt(context)
179	        ? { label: 'Check plan', onClick: onCheckPlan } : undefined} />
180	      <hr className="current-setup-divider" />
181	    </>}
182	    <div className="current-setup-facts">
183	      <p className="current-setup-facts-text" title={presets}>{presets || 'No settings read from the project'}</p>
184	      {onViewSetup && presets && offers && <button type="button" className="current-setup-link" onClick={onViewSetup}>All settings</button>}
185	    </div>
186	    <Note text={presetsNote(context)} />
187	    {estimate.metrics.length > 0
188	      ? <div className="current-setup-metrics">
189	        {estimate.metrics.map((metric) => <span className="current-setup-metric" key={metric.icon}>
190	          <span className={`jp-icon jp-icon-${metric.icon}`} aria-hidden="true" />{metric.text}</span>)}
191	        {estimate.plate && <span className="current-setup-metric">
192	          <span className="jp-icon jp-icon-grid-3x3" aria-hidden="true" />{estimate.plate}</span>}
193	        {estimate.cost && <span className="current-setup-metric">{estimate.cost}</span>}
194	      </div>
195	      : <div className="current-setup-facts">
196	        <p className="current-setup-line">{estimate.line}</p>
197	        {live && estimate.status === 'none' && !estimate.sliced &&
198	          <button type="button" className="current-setup-link" onClick={onCompute}>Slice to see time and filament</button>}
199	      </div>}
200	    <Note text={estimate.status === 'stale' ? 'From before the last change.' : ''}
201	      action={live ? { label: 'Slice again to update', onClick: onCompute! } : undefined} />
202	    {!historical && !agentAvailable && <p className="current-setup-line">{changedSettingCount(context) > 0
203	      ? 'No AI configured.' : 'No AI configured · using the selected preset.'}</p>}
204	    {historical && <p className="current-setup-line">{sent
205	      ? `${sent.printer ? `Sent to ${sent.printer}` : 'Sent'}${sentWhen ? ` · ${sentWhen}` : ''}. Saved snapshot: the canvas shows your current project.`
206	      : 'Saved with this chat. The canvas shows your current project.'}</p>}
207	  </section>;
208	}
