(function(){
  const css = `
  .printer-header{display:none!important}
  html,body{height:100%}
  body{padding-top:56px;box-sizing:border-box}
  #root,.app{height:calc(100vh - 56px)!important;min-height:0!important}
  #winhdr{position:fixed;left:0;top:0;right:0;height:56px;display:flex;align-items:center;gap:12px;padding:0 24px;border-bottom:1px solid var(--border-subtle);background:var(--surface-canvas);z-index:50;box-sizing:border-box}
  #winhdr .nb{width:32px;height:32px;box-sizing:border-box;border:1px solid var(--border-subtle);border-radius:var(--radius-small);display:inline-flex;align-items:center;justify-content:center;color:var(--text-primary);background:var(--surface-canvas)}
  #winhdr svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
  #winhdr .t{font:var(--font-body-bold);color:var(--text-primary)}
  #winhdr .lk{margin-left:auto}`;
  const go = () => {
    const link = [...document.querySelectorAll('.printer-header .panel-link-button')].find(b => !b.classList.contains('panel-back-link'));
    if (!link) return setTimeout(go, 50);
    const s = document.createElement('style'); s.textContent = css; document.head.appendChild(s);
    const h = document.createElement('div'); h.id = 'winhdr';
    h.innerHTML = '<span class="nb" aria-label="Close"><svg viewBox="0 0 24 24"><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg></span><span class="t">Add a printer</span>';
    const l = link.cloneNode(true); l.classList.add('lk'); h.appendChild(l);
    document.body.appendChild(h);
  };
  window.addEventListener('DOMContentLoaded', go);
})();
.app--printer-setup, .app--focused-chat {
  background: var(--surface-canvas);
  padding: 16px;
}
.app--printer-setup > .chat-content, .app--focused-chat > .chat-content {
  width: 100%;
  max-width: var(--printer-setup-width);
  margin-inline: auto;
}
.app--printer-setup .printer-header, .app--focused-chat .printer-header {
  height: auto;
  flex-wrap: wrap;
  justify-content: space-between;
  border-bottom: none;
  padding: 8px 16px;
}
/* The chat header is one 44 DIP row; the chat list's own header is the
   taller 56 DIP panel header with its Section title. */
.chat-header, .chat-list-header {
  display: flex;
  flex: 0 0 auto;
   thread instead of the project's setup card, and the cards the agent draws
   inside it. Every value here resolves through the token variables. */

.app--printer {
  height: 100%;
}

.printer-header h1 {
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font: var(--font-body-bold);
  color: var(--text-primary);
}

  margin: 0;
  font: var(--font-label);
  color: var(--text-secondary);
}

.panel-back-link { display: inline-flex; align-items: center; gap: 4px; }

/* -- The All settings panel ------------------------------------------------
   Every setting in force, in the pane's place: the setup card's "All
   settings" link opens it. Its own prefix; the design system's Select,
   Field/Search, Segmented Control and Swatch are drawn from their recipes. */
