.jump-to-latest {
  position: absolute;
  left: 50%;
  bottom: 8px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--button-icon-width);
  height: var(--button-icon-height);
  padding: 0;
  border: none;
  border-radius: var(--radius-full);
  background: var(--surface-canvas);
  color: var(--text-primary);
  box-shadow: inset 0 0 0 1px var(--border-subtle), var(--elevation-subtle);
  cursor: pointer;
}

.jump-to-latest:hover { background: var(--surface-subtle); }
.jump-to-latest:active { background: var(--surface-selected); }

/* Chat navigation: the header and configuration footer stay outside the
   scrolling content so both remain reachable in a short or narrow dock. */
.chat-content { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.chat-content[hidden] { display: none; }

/* A temporary task chat takes the current workspace; its conversation keeps a
   reading width. */
.app--printer-setup, .app--focused-chat {
  font: var(--font-body-small-bold);
}
.settings-changes-more:hover:enabled { background: var(--surface-subtle); }

.change-revert-action { position: relative; flex: 0 0 auto; }
.change-revert-button {
  width: var(--button-icon-width);
  height: var(--button-icon-height);
  padding: 0;
  color: var(--text-secondary);
  border: 1px solid transparent;
}
.change-revert-button:hover,
.change-revert-button[aria-expanded="true"] { color: var(--action-primary); background: var(--surface-subtle); }
.change-revert-icon {
  display: block;
  width: var(--button-icon-icon-size);
  height: var(--button-icon-icon-size);
  background: currentColor;
  -webkit-mask: url('@resources/jusprin/ui/icons/undo-dot.svg') center / contain no-repeat;
  mask: url('@resources/jusprin/ui/icons/undo-dot.svg') center / contain no-repeat;
}
.change-revert-tooltip {
  display: none;
  position: absolute;
  z-index: 3;
}

/* + is Button/Icon without a stroke: the box around it is the boundary. */
.composer-choices button.chat-icon {
  width: var(--button-icon-width);
  height: var(--button-icon-height);
  padding: 0;
  border-color: transparent;
  background: transparent;
  color: var(--text-primary);
}

.composer-choices button.chat-icon:hover:enabled {
  border-color: transparent;
  background: var(--surface-subtle);
}
