/* The JusPrin lockup › Home, and Preferences, the height of the project
   header it stands in for. */
.home-header {
  flex: 0 0 var(--home-header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  border-bottom: 1px solid var(--border-subtle);
}

.home-header-path {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--text-secondary);
}

.home-header-lockup {
  display: block;
  height: var(--home-header-lockup-height);
}

.home-header-page {
  font: var(--font-body);
}

/* The gallery and the printer rail, side by side under the header. */
.home-body {
  flex: 1 1 auto;
  display: flex;
  min-height: 0;
}

.app.connecting {
  cursor: pointer;
}

.printer-menu-button .glyph,
/* The header's one control, at the weight of the text beside it. */
.home-header .preferences-button {
  color: var(--text-primary);
}

.preferences-button .glyph {
  width: var(--button-icon-icon-size);
  height: var(--button-icon-icon-size);
}

.printer-menu-button:hover,
.preferences-button:hover,
.printer-menu-button[aria-expanded='true'] {
  color: var(--text-primary);
  background: var(--surface-subtle);
}

.printer-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 2;
