import { useEffect, useRef, useState } from 'react';
import { McpCatalogPayload, McpPreviewPayload, McpStatusPayload, McpToolInfo } from '../bridge/protocol';
import { ToolGroup } from './AgentConnection';

// The screen's title is its way back: one target, the chevron and the name.
function SetupScreenTitle({ label, onBack }: { label: string; onBack: () => void }) {
  return (
    <h1 className="setup-title">
      <button type="button" className="setup-back" onClick={onBack} aria-label="Back to setup options">
        <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" />
        {label}
      </button>
    </h1>
  );
}

type Step = 'pick' | 'prepare' | 'review' | 'saving' | 'saved';

export interface SetupLocalToolProps {
  catalog: McpCatalogPayload | null;
  preview: McpPreviewPayload | null;
  status: McpStatusPayload;
  onRefresh: () => void;
  onPreview: (toolId: string) => void;
  onConnect: (toolId: string) => void;
  onReveal: (toolId: string) => void;
  onBack: () => void;
  onDone: () => void;
  // Opens on this tool's own screen, as Preferences does from its row; that
  // screen's way back is then onBack, since the list it came from is not here.
    if (cell?.inherited) return cell.inheritedDisplay ?? '';
  }
  return '';
}

// -- The panel ------------------------------------------------------------------

export function AllSettingsHeader({ onBack, onCollapse }: { onBack: () => void; onCollapse: () => void }) {
  return <header className="chat-header all-settings-header">
    <button type="button" className="chat-icon" aria-label="Back to chat" title="Back to chat" autoFocus onClick={onBack}>
      <span className="jp-icon jp-icon-chevron-left" aria-hidden="true" />
    </button>
    <h1>All settings</h1>
    <AgentPaneToggle onCollapse={onCollapse} />
  </header>;
}

function scopeKey(scope: SettingsScope): string {
  return scope.kind === 'project' ? 'project' : `${scope.kind}:${scope.id}`;
}

